from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def main():
 base=ROOT/'versions/v0132-f1537f6f';old=(base/'actors.c').read_text();s=(ROOT/'megadrive/src/actors.c').read_text()
 a=s.index('extern const u8 dungeon_ambush_vectors[];');b=s.index('/* 5071 -> A86D:',a);s=s[:a]+s[b:]
 dispatch='            else if(entity[0]==0x52) dungeon_ambush_behavior(entity,cells,hero_x,hero_y,frame,slot,NULL);\n';assert s.count(dispatch)==1;s=s.replace(dispatch,'').replace('(entity[0]>=0x4a && entity[0]<=0x52)','(entity[0]>=0x4a && entity[0]<=0x51)');assert s==old,'Unrelated actor code changed'
 main=(ROOT/'megadrive/src/main.c').read_text();block='/* 2CD5/9EB1: low tile bytes at center cache positions5/6, before movement. */\nstatic bool hero_floor_zero=TRUE; /* Original boot cache C052/C054 is zero. */\nvoid world_set_hero_floor(u8 left,u8 right) { hero_floor_zero=!left || !right; }\nbool world_hero_zero_floor(void) { return hero_floor_zero; }\n';sample='            world_set_hero_floor(offset+66<0x600?sms_vram[0x3800+offset+66]:255,\n                                 offset+68<0x600?sms_vram[0x3800+offset+68]:255);\n';assert main.count(block)==main.count(sample)==1;assert main.replace(block,'').replace(sample,'')==(base/'main.c').read_text()
 source=(ROOT/'input/original.sms').read_bytes();assert source[0x9eb1:0x9eb4]==bytes.fromhex('3a52c0') and source[0x9eb7:0x9eba]==bytes.fromhex('3a54c0') and source[0x2cd5:0x2cd8]==bytes.fromhex('1148c0')
 asset=ROOT/'megadrive/src/dungeon_ambush_data.c';literal=bytes(int(x,16) for x in re.findall(r'0x([0-9a-fA-F]{2})',asset.read_text()));assert literal==source[0x9f61:0x9f81]
 data=(ROOT/'gaw-megadrive.bin').read_bytes();assert len(data)==1048576 and data==(ROOT/'gaw-title-megadrive.bin').read_bytes()==(ROOT/'megadrive/out/release/rom.bin').read_bytes();checksum=sum(int.from_bytes(data[i:i+2],'big') for i in range(0x200,len(data),2))&65535;assert int.from_bytes(data[0x18e:0x190],'big')==checksum
 assert data[0x1a4:0x1a8]==bytes.fromhex('000fffff') and data[0x1b0:0x1b4]==bytes.fromhex('5241f820')
 entry=json.loads((ROOT/'validation/dungeon_ambush_entry_report.json').read_text());assert entry['md_sha256']==sha(ROOT/'gaw-megadrive.bin')
 delays=[dict(region=c['region'],source=c['arrival_frames']['sms']-3500,native=c['arrival_frames']['md']-3500) for c in entry['cases']]
 report=dict(md_sha256=sha(ROOT/'gaw-megadrive.bin'),source_sha256=sha(ROOT/'input/original.sms'),rom_bytes=len(data),checksum=checksum,aliases_and_header_verified=True,production_changes_confined_to_52_AI_dispatch_publication_and_pre_movement_floor_cache=True,prior_actor_and_main_implementations_unchanged_since_v0132=True,literal_bytes_exact=32,source_cache_low_offsets=[0x52,0x54],cache_word_indices=[5,6],observed_random_placement_delays=delays,original_random_stream_reproduced=False,source_files={str(p.relative_to(ROOT)):sha(p) for p in [ROOT/'megadrive/src/main.c',ROOT/'megadrive/src/actors.c',asset,ROOT/'tools/validate_dungeon_ambush.py',ROOT/'tools/validate_dungeon_ambush_gameplay.py',ROOT/'tools/validate_dungeon_ambush_entry.py']},full_game_ported=False,limits=['Controlled actor/hero/floor state injection and initial native clock alignment; real pre-movement cache order checked by a fractional-position crossing.','Actual119 remains inactive at3490, triggers at3500 after hero relocation onto unchanged floor72,80, then random placement delays differ as recorded.','Appearance records align to first initialized state4, exclude random X/Y/direction and do not prove absolute appearance timing. Full natural combat, RNG/global clock and framebuffer/SAT remain unproved.'])
 (ROOT/'validation/dungeon_ambush_patch_audit.json').write_text(json.dumps(report,indent=2)+'\n');print('Only52 AI and pre-movement floor cache added;32 literal bytes and ROM integrity verified. Placement timing remains different.')
